import unittest
from textwrap import dedent

from ansible.errors import AnsibleFilterError

from filter_plugins.bisdn_ports import bisdn_breakouts, bisdn_fec, bisdn_port_map

# excerpt of an AS7726-32X config.bcm after ofdpa-breakout split port4 into 4x25G
CONFIG_BCM = dedent("""\
    # GENERATED by ofdpa-breakout, edit config.bcm.dist and breakout.conf instead
    pbmp_xport_xe=0x4888888888888888c22222222222221e2
    portmap_1.0=1:100
    phy_chain_tx_lane_map_physical{1.0}=0x3210
    portmap_5.0=5:100
    portmap_13.0=13:25
    # port4 split into 4x25G: lanes 2-4 are port35, port36, port37
    portmap_14.0=14:25
    portmap_15.0=15:25
    portmap_16.0=16:25
    portmap_66.0=129:10:m
    portmap_130.0=128:10:m
    portmap_131.0=131:100
    dport_map_port_1=1
    dport_map_port_5=2
    dport_map_port_13=4
    dport_map_port_14=35
    dport_map_port_15=36
    dport_map_port_16=37
    dport_map_port_66=33
    dport_map_port_130=34
    """)


class BreakoutsTest(unittest.TestCase):
    def test_breakouts_sorted_by_front_panel_number(self):
        self.assertEqual(
            bisdn_breakouts({"port10": "4x25G", "port4": "4x10G"}),
            [
                dict(port="port4", panel=4, lanes=4, speed=10),
                dict(port="port10", panel=10, lanes=4, speed=25),
            ],
        )

    def test_unchanged_ports_are_dropped(self):
        self.assertEqual(bisdn_breakouts({"port1": "1x100G[40G]", "port2": "1x100G", "port3": "4x25G"}),
                         [dict(port="port3", panel=3, lanes=4, speed=25)])

    def test_empty(self):
        self.assertEqual(bisdn_breakouts({}), [])
        self.assertEqual(bisdn_breakouts(None), [])

    def test_invalid_mode(self):
        for mode in ("2x50G", "4x25", "4x100G", "", 25):
            with self.subTest(mode=mode), self.assertRaisesRegex(AnsibleFilterError, "port4: breakout"):
                bisdn_breakouts({"port4": mode})

    def test_invalid_port_name(self):
        for name in ("Ethernet12", "port0", "port", "port4.1"):
            with self.subTest(name=name), self.assertRaisesRegex(AnsibleFilterError, "not a BISDN front panel port"):
                bisdn_breakouts({name: "4x25G"})

    def test_not_a_dict(self):
        with self.assertRaisesRegex(AnsibleFilterError, "must map port<N>"):
            bisdn_breakouts(["port4"])


class PortMapTest(unittest.TestCase):
    def test_front_panel_ports_with_logical_port_and_speed(self):
        ports = bisdn_port_map(CONFIG_BCM)
        self.assertEqual(ports["port1"], dict(panel=1, logical=1, speed=100))
        self.assertEqual(ports["port2"], dict(panel=2, logical=5, speed=100))
        self.assertEqual(ports["port4"], dict(panel=4, logical=13, speed=25))
        self.assertEqual(ports["port35"], dict(panel=35, logical=14, speed=25))
        self.assertEqual(ports["port33"], dict(panel=33, logical=66, speed=10))

    def test_logical_ports_without_front_panel_number_are_left_out(self):
        self.assertEqual(sorted(bisdn_port_map(CONFIG_BCM), key=lambda p: int(p[4:])),
                         ["port1", "port2", "port4", "port33", "port34", "port35", "port36", "port37"])

    def test_dport_without_portmap(self):
        with self.assertRaisesRegex(AnsibleFilterError, "dport_map_port_7=9 has no portmap_7"):
            bisdn_port_map(CONFIG_BCM + "dport_map_port_7=9\n")

    def test_no_dport_map(self):
        with self.assertRaisesRegex(AnsibleFilterError, "no dport_map_port"):
            bisdn_port_map("portmap_1.0=1:100\n")


class FECTest(unittest.TestCase):
    ports = bisdn_port_map(CONFIG_BCM)

    def fec(self, conf):
        return [(f["port"], f["clause"]) for f in bisdn_fec(conf, self.ports)]

    def test_overrides_on_default_none(self):
        self.assertEqual(
            self.fec({"default_fec": "none", "list": [{"name": "port2", "fec": "rs"}, {"name": "port1", "fec": "rs"}]}),
            [("port1", "cl91"), ("port2", "cl91")],
        )

    def test_rs_on_a_25g_lane_is_clause_108(self):
        self.assertEqual(self.fec({"list": [{"name": "port35", "fec": "rs"}]}), [("port35", "cl108")])

    def test_fc_is_clause_74(self):
        self.assertEqual(self.fec({"list": [{"name": "port4", "fec": "fc"}, {"name": "port33", "fec": "fc"}]}),
                         [("port4", "cl74"), ("port33", "cl74")])

    def test_default_applies_where_the_speed_supports_it(self):
        # port33/34 run at 10G, where rs has no clause: the default skips them
        self.assertEqual(
            self.fec({"default_fec": "rs", "list": [{"name": "port2", "fec": "none"}, {"name": "port36"}]}),
            [("port1", "cl91"), ("port4", "cl108"), ("port35", "cl108"), ("port36", "cl108"), ("port37", "cl108")],
        )

    def test_entry_without_fec_takes_the_default(self):
        self.assertEqual(self.fec({"default_fec": "none", "list": [{"name": "port1"}]}), [])

    def test_empty(self):
        self.assertEqual(self.fec({}), [])
        self.assertEqual(self.fec(None), [])

    def test_explicit_fec_must_fit_the_speed(self):
        with self.assertRaisesRegex(AnsibleFilterError, "port33: fec rs is not supported at 10G, only at 25G, 100G"):
            bisdn_fec({"list": [{"name": "port33", "fec": "rs"}]}, self.ports)

    def test_unknown_port(self):
        with self.assertRaisesRegex(AnsibleFilterError, r"list\[0\]: unknown port 'Ethernet0', this switch has port1, port2"):
            bisdn_fec({"list": [{"name": "Ethernet0", "fec": "rs"}]}, self.ports)

    def test_unknown_mode(self):
        with self.assertRaisesRegex(AnsibleFilterError, r"list\[0\] \(port1\): fec 'auto'"):
            bisdn_fec({"list": [{"name": "port1", "fec": "auto"}]}, self.ports)
        with self.assertRaisesRegex(AnsibleFilterError, "default_fec: fec 'RS'"):
            bisdn_fec({"default_fec": "RS"}, self.ports)

    def test_unknown_keys(self):
        with self.assertRaisesRegex(AnsibleFilterError, r"list\[0\]: unknown keys fecc"):
            bisdn_fec({"list": [{"name": "port1", "fecc": "rs"}]}, self.ports)
        with self.assertRaisesRegex(AnsibleFilterError, "bisdn_config_ports: unknown keys default_mtu"):
            bisdn_fec({"default_mtu": 9000}, self.ports)

    def test_entry_without_name(self):
        with self.assertRaisesRegex(AnsibleFilterError, r"list\[0\]: want \{name"):
            bisdn_fec({"list": [{"fec": "rs"}]}, self.ports)


if __name__ == "__main__":
    unittest.main()
